REPLAY_PRESENTER_VERSION="1.0"
class ReplayPresenterSectionKey(StrEnum): STATUS_BANNER="status_banner"; HEADER="header"; HERO="replay_hero"; PROGRESS="replay_progress"; DECISION="decision_summary"; COMPARISON="frame_comparison"; TIMEFRAMES="timeframe_cards"; MODULES="module_cards"; MESSAGES="messages"; FOOTER="footer"
class ReplayPresenterThemeState(StrEnum): NORMAL="normal"; CALM="calm"; CHANGED="changed"; WAITING="waiting"; CAUTION="caution"; DANGER="danger"; UNAVAILABLE="unavailable"
