 def __post_init__(self):
  if self.presenter_version!=REPLAY_PRESENTER_VERSION or self.section_order!=tuple(ReplayPresenterSectionKey) or self.timeframe_order!=("15m","60m","1d","1w") or self.module_order!=("position","trend","structure","timing") or min(self.warning_limit,self.message_limit,self.changed_field_limit)<=0 or self.language!="zh-TW": raise ValueError("Invalid Replay presenter config")
