def _text(value,config):
 text="無法取得" if value is None else str(getattr(value,"value",value)); return escape(text,quote=True) if config.html_escape else text
def _score(value): return "無法取得" if value is None else (f"{value:.0f}" if hasattr(value,"__float__") and float(value).is_integer() else str(value))
def _theme(model):
 state=model.display_state.value; comparison=model.comparison.comparison_state.value
 return ReplayPresenterThemeState.UNAVAILABLE if state in {"invalid","unavailable"} else ReplayPresenterThemeState.DANGER if state=="blocked" else ReplayPresenterThemeState.CAUTION if state=="stale" else ReplayPresenterThemeState.CHANGED if comparison in {"changed","partially_changed"} else ReplayPresenterThemeState.CALM if comparison=="unchanged" else ReplayPresenterThemeState.NORMAL
